PORT, server = _srv.start(ROOT, ['preview'])  # her koşu kendi boş portunda kendi sunucusunu açar (test/_srv.py)

def near(a, b, tol=2e-3): return a is not None and abs(a - b) <= tol * max(1, abs(b))

