    stepA = os.path.join(TMP, 'sec_A.step'); stepB = os.path.join(TMP, 'sec_B.step')
    open(stepA, 'wb').write(base64.b64decode(step_b64(10))); open(stepB, 'wb').write(base64.b64decode(step_b64(20)))
